// Process Control Block (PCB) structure
struct PCB {
    pid_t pid;
    // Core CPU State Storage
    struct {
        uint64_t R[16], PC, SP;
        uint64_t MMU_CR3; // Page Table Base Register
    } saved_state;
};

// Intrinsic functions (low-level assembly required)
extern void save_CPU(void* reg_storage);
extern void restore_CPU(void* reg_storage);
extern void set_MMU_base(uint64_t addr);

// Kernel function executing the switch
void kernel_context_switch(struct PCB* current, struct PCB* next) {
    // 1. Save state of the current process
    save_CPU(&current->saved_state);

    // 2. Change Memory Address Space
    set_MMU_base(next->saved_state.MMU_CR3);

    // 3. Load state of the next process
    restore_CPU(&next->saved_state);
    // Control resumes at next->saved_state.PC
}
